#!/usr/bin/env python3
"""art/export/*.bin (car triangles) + art/export/stages.json -> native/src/world_data.cpp (generated by tools/godot/export.gd)."""
import json, os, struct
HERE = os.path.dirname(__file__)
EX = os.path.join(HERE, '..', 'art', 'export')
OUT = os.path.join(HERE, '..', 'native', 'src', 'world_data.cpp')
ORDER = ["hatch", "buggy", "muscle", "sierra", "pickup", "charger", "coupe", "m4", "gt3", "hyper"]
L = ['// GENERATED by tools/make_world_data.py - do not edit.', '#include "world_data.h"', '#include <cstdint>', '']
for n in ORDER:
    b = open(os.path.join(EX, n + '.bin'), 'rb').read()
    cnt = struct.unpack('<I', b[:4])[0]
    assert len(b) == 4 + cnt * 22, (n, len(b), cnt)
    body = b[4:]
    L.append(f'static const uint8_t CAR_{n}[{len(body)}] = {{')
    for i in range(0, len(body), 48):
        L.append(','.join(str(v) for v in body[i:i + 48]) + ',')
    L.append('};')
wheels = json.load(open(os.path.join(EX, 'wheels.json')))
for n in ORDER:
    b = open(os.path.join(EX, n + '_wheel.bin'), 'rb').read()
    cnt = struct.unpack('<I', b[:4])[0]
    assert len(b) == 4 + cnt * 22, (n, 'wheel')
    body = b[4:] if cnt else b'\0'
    L.append(f'static const uint8_t WHEEL_{n}[{len(body)}] = {{')
    for i in range(0, len(body), 48):
        L.append(','.join(str(v) for v in body[i:i + 48]) + ',')
    L.append('};')
L.append('const CarMeshData CAR_MESHES[CAR_MESH_COUNT] = {')
for n in ORDER:
    cnt = struct.unpack('<I', open(os.path.join(EX, n + '.bin'), 'rb').read(4))[0]
    wcnt = struct.unpack('<I', open(os.path.join(EX, n + '_wheel.bin'), 'rb').read(4))[0]
    w = wheels[n]
    L.append(f'    {{"{n}", {cnt}, CAR_{n}, {wcnt}, WHEEL_{n}, {{{w[0]:g},{w[1]:g},{w[2]:g},{w[3]:g}}}}},')
L.append('};')
stages = json.load(open(os.path.join(EX, 'stages.json')))
for si, st in enumerate(stages):
    pts = st['points']
    L.append(f'static const StagePt PTS_{si}[{len(pts)}] = {{')
    L.append(','.join('{%g,%g,%g,%g,%d}' % tuple(p) for p in pts))
    L.append('};')
    obs = st['obstacles']
    L.append(f'static const StageObs OBS_{si}[{max(1, len(obs))}] = {{')
    kinds = {'rock': 0, 'log': 1, 'bump': 2}
    L.append(','.join('{%d,%d,%d}' % (o[0], kinds.get(o[1], 0), o[2]) for o in obs) if obs else '{0,0,0}')
    L.append('};')
L.append('const StageData STAGES[STAGE_COUNT] = {')
for si, st in enumerate(stages):
    L.append('    {"%s", "%s", %g, %d, PTS_%d, %d, OBS_%d},' % (st['name'].upper(), st['theme'], st['relief'], len(st['points']), si, len(st['obstacles']), si))
L.append('};')
open(OUT, 'w').write('\n'.join(L) + '\n')
print('wrote', OUT, os.path.getsize(OUT) // 1024, 'KB')
